import css from "./styles.css";
import { renderDashboard } from "./ui/dashboard";
import { renderLibrary } from "./ui/library";
import { renderSpaceDialog } from "./ui/space";
import { renderJsonWorkspace } from "./ui/jsonWorkspace";
import { renderCategoryWorkspace } from "./ui/categoryWorkspace";
import type { CategoryKey } from "./ui/constants";

const CATEGORY_WORKSPACES: readonly CategoryKey[] = [
  "text",
  "data",
  "seo",
  "images",
  "social",
];

export const render = (): string => {
  const dom = new DOM();
  const shellClass = dom.createClassFromStyle(css.shell);
  const dashboardClass = dom.createClassFromStyle(css.dashboard);
  const cardClass = dom.createClassFromStyle(css.card);
  const libraryClass = dom.createClassFromStyle(css.library);
  const workspaceClass = dom.createClassFromStyle(css.workspace);
  const resultClass = dom.createClassFromStyle(css.result);
  const dockClass = dom.createClassFromStyle(css.dock);
  const categoryWorkspaces = CATEGORY_WORKSPACES.map(
    (key) =>
      dom.createElement(
        "div",
        { class: workspaceClass, hidden: "", "data-category": key },
        renderCategoryWorkspace(key)
      )
  ).join("");
  return dom.renderHTML(
    dom.createElement(
      "div",
      { class: shellClass, "data-role": "tool-workbench" },
      dom.createElement(
        "div",
        { class: dashboardClass, "data-role": "tool-dashboard-shell" },
        renderDashboard(cardClass)
      ),
      dom.createElement(
        "div",
        { class: libraryClass, "data-role": "tool-library-shell" },
        renderLibrary()
      ),
      dom.createElement(
        "div",
        { class: workspaceClass, "data-role": "tool-json-shell", hidden: "" },
        renderJsonWorkspace(resultClass)
      ),
      categoryWorkspaces,
      dom.createElement(
        "div",
        { class: resultClass, "data-role": "tool-space-shell" },
        renderSpaceDialog()
      ),
      dom.createElement(
        "div",
        { class: dockClass, "data-role": "tool-dock" },
        "Local tools \u2014 no network, no cloud."
      )
    )
  );
};

