import { escapeHTML, createElement, buildButton, buildTile } from "./dom";
import { CATEGORIES, ROLES } from "./constants";

export const renderDashboard = (): string => {
  const brand = createElement("div", {
    attrs: { "data-role": ROLES.BRAND, class: "brand" },
    children: [
      createElement("span", { attrs: { class: "brand-mark", "aria-hidden": "true" } }, "⌘"),
      createElement("span", { attrs: { class: "brand-name" } }, "Workbench"),
    ],
  });

  const quickJson = buildTile({
    name: "JSON Formatter",
    hint: "Format & validate",
    dataRole: ROLES.CARD_JSON,
    icon: "{}",
    variant: "card-json",
    ariaLabel: "Open JSON Formatter",
  });

  const categoryTiles = CATEGORIES.map((c) =>
    buildTile({
      name: c.label,
      hint: c.hint,
      dataRole: ROLES.CATEGORY_CARD[c.key],
      icon: c.icon,
      variant: `card-${c.key}`,
      ariaLabel: `Open ${c.label}`,
    }),
  );

  const quickAccess = createElement("section", {
    attrs: { class: "quick-access" },
    children: [
      createElement("h2", { attrs: { class: "wt-section-label" } }, "Quick Access"),
      createElement("div", { attrs: { class: "quick-row" } }, [quickJson]),
    ],
  });

  const categories = createElement("section", {
    attrs: { class: "categories" },
    children: [
      createElement("h2", { attrs: { class: "wt-section-label" } }, "Categories"),
      createElement("div", { attrs: { class: "category-grid" } }, [...categoryTiles]),
    ],
  });

  const dashboardHeader = createElement("header", {
    attrs: { class: "dashboard-header" },
    children: [
      createElement("h1", { attrs: { class: "dashboard-title" } }, "Web Tools Workbench"),
      createElement(
        "p",
        { attrs: { class: "dashboard-subtitle" } },
        "Everyday developer and webmaster utilities, all right in your browser.",
      ),
    ],
  });

  const header = createElement("header", {
    attrs: { class: "topbar" },
    children: [
      brand,
      createElement("div", {
        attrs: { class: "topbar-actions" },
        children: [
          buildButton({
            label: "Library",
            dataRole: ROLES.LIBRARY_BUTTON,
            type: "button",
            classes: "wt-ghost topbar-btn",
            ariaLabel: "Open tool library",
            icon: "📚",
          }),
          buildButton({
            label: "My Space",
            dataRole: ROLES.SPACE_BUTTON,
            type: "button",
            classes: "wt-ghost topbar-btn",
            ariaLabel: "Open personal space",
            icon: "✦",
          }),
        ],
      }),
    ],
  });

  return createElement("div", {
    attrs: { "data-role": ROLES.WORKBENCH, class: "shell wt-anim" },
    children: [
      header,
      createElement("main", {
        attrs: { "data-role": ROLES.DASHBOARD, class: "dashboard" },
        children: [dashboardHeader, quickAccess, categories],
      }),
    ],
  });
};

