import { createElement, buildButton, buildRow, escapeHTML } from "./dom";
import { ROLES, CATEGORIES } from "./constants";

export const renderLibrary = (): string => {
  const quickRows = [
    { key: "json", label: "JSON Formatter", hint: "Format and validate JSON" },
    ...CATEGORIES.map((c) => ({
      key: c.key,
      label: c.label,
      hint: c.hint,
    })),
  ];

  const searchField = createElement("label", {
    attrs: { class: "library-search" },
    children: [
      createElement("span", {
        attrs: { class: "wt-label" },
        children: ["Search tools"],
      }),
      createElement("input", {
        attrs: {
          type: "search",
          id: "tool-search",
          "data-role": ROLES.SEARCH,
          class: "library-search-input",
          placeholder: "Search for a tool or category…",
          autocomplete: "off",
        },
      }),
    ],
  });

  const chips = [
    { key: "all", label: "All" },
    ...CATEGORIES.map((c) => ({ key: c.key, label: c.label })),
  ]
    .map(
      (c) =>
        createElement("button", {
          attrs: {
            type: "button",
            class: "library-chip" + (c.key === "all" ? " library-chip-active" : ""),
            "data-library-filter": c.key,
          },
          children: [escapeHTML(c.label)],
        }),
    )
    .join("");

  const rows = quickRows
    .map((r) =>
      r.key === "json"
        ? buildButton({
            label: r.label,
            dataRole: ROLES.OPEN_JSON,
            classes: "library-row",
            ariaLabel: `Open ${r.label}`,
            attrs: { "data-tool-key": r.key },
          })
        : buildRow({
            name: r.label,
            hint: r.hint,
            dataRole: `tool-library-card-${r.key}`,
            attrs: { "data-tool-key": r.key },
          }),
    )
    .join("");

  const openJson = buildButton({
    label: "JSON Formatter",
    dataRole: ROLES.OPEN_JSON,
    classes: "wt-primary library-row",
    ariaLabel: "Open JSON Formatter",
    attrs: { "data-tool-key": "json" },
  });

  return createElement("section", {
    attrs: {
      "data-role": ROLES.LIBRARY,
      "data-state": "closed",
      class: "library",
      "aria-label": "Tool library",
      "aria-hidden": "true",
    },
    children: [
      createElement("div", {
        attrs: { class: "library-panel" },
        children: [
          createElement("header", {
            attrs: { class: "library-header" },
            children: [
              createElement("h2", {
                attrs: { class: "library-title" },
                children: ["Tool library"],
              }),
              buildButton({
                label: "×",
                dataRole: ROLES.LIBRARY_CLOSE,
                classes: "library-close",
                ariaLabel: "Close tool library",
                icon: "fa fa-times",
              }),
            ],
          }),
          searchField,
          createElement("div", {
            attrs: { class: "library-filters" },
            children: [chips],
          }),
          createElement("div", {
            attrs: { class: "library-section-label" },
            children: ["Quick access"],
          }),
          createElement("div", {
            attrs: { class: "library-rows" },
            children: [openJson, rows],
          }),
        ],
      }),
    ],
  });
};

