import { createElement, buildButton, buildRow, escapeHTML } from "./dom";
import { ROLES } from "./constants";

export const renderSpaceDialog = (): string => {
  const close = buildButton({
    label: "Close",
    dataRole: ROLES.SPACE_CLOSE,
    type: "button",
    classes: "space-close",
    ariaLabel: "Close personal space",
  });

  const header = createElement("div", {
    attrs: { class: "space-header" },
    children: [
      createElement("h2", { attrs: { class: "space-title" }, children: ["My Space"] }),
      close,
    ],
  });

  const tabs = createElement("div", {
    attrs: { class: "space-tabs", role: "tablist", "aria-label": "Personal space sections" },
    children: [
      createElement("button", {
        attrs: {
          type: "button",
          class: "space-tab space-tab-active",
          role: "tab",
          "aria-selected": "true",
        },
        children: ["Saved"],
      }),
      createElement("button", {
        attrs: { type: "button", class: "space-tab", role: "tab", "aria-selected": "false" },
        children: ["Favourites"],
      }),
    ],
  });

  const rows = createElement("div", {
    attrs: { class: "space-rows" },
    children: [
      buildRow({
        name: "JSON Formatter",
        hint: "Formats and validates JSON text locally.",
        dataRole: "tool-space-row-json",
        icon: "{}",
      }),
      buildRow({
        name: "Text & Content",
        hint: "Transforms text and reports counts.",
        dataRole: "tool-space-row-text",
        icon: "T",
      }),
      buildRow({
        name: "Web & SEO",
        hint: "Inspects pasted HTML for SEO coverage.",
        dataRole: "tool-space-row-seo",
        icon: "#",
      }),
    ],
  });

  const sections = createElement("div", {
    attrs: { class: "space-section" },
    children: [
      createElement("div", {
        attrs: { class: "space-section-label" },
        children: ["Saved tools"],
      }),
      rows,
    ],
  });

  const privacy = createElement("p", {
    attrs: { class: "space-privacy" },
    children: [
      "Everything in this workspace runs in your browser. No data leaves this page, and no network calls are made.",
    ],
  });

  const sheet = createElement("div", {
    attrs: { class: "space-sheet", role: "dialog", "aria-modal": "true", "aria-label": "Personal space" },
    children: [header, tabs, sections, privacy],
  });

  return createElement("div", {
    attrs: {
      class: "space-dialog",
      "data-role": ROLES.SPACE_DIALOG,
      "data-state": "closed",
    },
    children: [sheet],
  });
};

