import { escapeHTML, createElement, buildButton, buildLabelledField } from "./dom";
import { ROLES } from "./constants";

/**
 * Renders the JSON Formatter work surface.
 * Uses an ivory workspace with back action, a pure-form formatter,
 * and a result pane that reflects ready / success / error states.
 */
export const renderJsonWorkspace = (): string => {
  const header = createElement("header", {
    attrs: { class: "workspace-header" },
    children: [
      buildButton({
        label: "Back to dashboard",
        dataRole: ROLES.BACK_DASHBOARD,
        type: "button",
        classes: "workspace-back wt-ghost",
        ariaLabel: "Back to dashboard",
      }),
      createElement("div", {
        attrs: {},
        children: [
          createElement("h2", { attrs: { class: "workspace-title" }, children: ["JSON Formatter"] }),
          createElement("p", { attrs: { class: "workspace-subtitle" }, children: ["Paste any JSON document and format it with two-space indentation. Everything stays on this machine."] }),
        ],
      }),
    ],
  });

  const inputField = buildLabelledField({
    id: "json-input",
    label: "JSON input",
    type: "text",
    name: "json-input",
    value: "",
    placeholder: '{"name":"workbench","tools":["json","text","seo"]}',
    rows: 1,
  });

  const form = createElement("form", {
    attrs: {
      class: "pure-form pure-form-stacked json-form",
      "data-role": "json-form",
    },
    children: [
      inputField,
      createElement("div", {
        attrs: { class: "json-actions" },
        children: [
          buildButton({
            label: "Format JSON",
            dataRole: ROLES.FORMAT_JSON,
            type: "button",
            classes: "pure-button pure-button-primary json-primary",
          }),
        ],
      }),
    ],
  });

  const result = createElement("pre", {
    attrs: {
      class: "workspace-result json-result",
      "data-role": ROLES.JSON_RESULT,
      "data-state": "ready",
      "aria-live": "polite",
    },
    children: [escapeHTML("Formatted JSON will appear here after you run the formatter.")],
  });

  const root = createElement("section", {
    attrs: {
      class: "workspace json-workspace",
      "data-role": ROLES.WORKSPACE,
      "data-tool-category": "json",
      "aria-label": "JSON Formatter workspace",
    },
    children: [header, form, result],
  });

  return root;
};

