import { escapeHTML, createElement, buildButton, buildSelectField, buildLabelledField } from "./dom";
import { CATEGORIES, CATEGORY_SELECT_OPTIONS, ROLES } from "./constants";
import type { CategoryKey } from "./constants";

function buildSocialInputs(): string {
  return [
    buildLabelledField({
      id: "social-title",
      label: "Title",
      name: "title",
      type: "text",
      placeholder: "Page title",
    }),
    buildLabelledField({
      id: "social-description",
      label: "Description",
      name: "description",
      type: "text",
      placeholder: "Short summary",
    }),
    buildLabelledField({
      id: "social-url",
      label: "URL",
      name: "url",
      type: "text",
      placeholder: "https://example.com",
    }),
  ].join("\n");
}

function renderCategoryInputs(category: CategoryKey): string {
  if (category === "social") {
    return buildSocialInputs();
  }

  return buildLabelledField({
    id: "category-input",
    label: "Input",
    name: "input",
    type: "text",
    placeholder: "Paste text, JSON, HTML, a data URL, or SVG markup here.",
  });
}

export function renderCategoryWorkspace(category: CategoryKey): string {
  const meta = CATEGORIES.find((c) => c.key === category);
  const label = meta ? meta.label : category;
  const options = CATEGORY_SELECT_OPTIONS[category] ?? [];
  const showSelect = category === "text" || category === "data";

  const selectMarkup = showSelect
    ? buildSelectField({
        id: "category-select",
        label: "Operation",
        name: "operation",
        options,
      })
    : "";

  return createElement("section", {
    attrs: {
      class: "category-workspace workspace",
      "data-role": ROLES.CATEGORY_WORKSPACE,
      "data-tool-category": category,
      "data-state": "open",
    },
    children: [
      createElement("header", {
        attrs: { class: "category-workspace-header workspace-header" },
        children: [
          buildButton({
            label: "\u2190 Back",
            dataRole: ROLES.CATEGORY_BACK,
            classes: "category-back workspace-back wt-ghost",
            ariaLabel: "Back to dashboard",
          }),
          createElement("div", {
            attrs: {},
            children: [
              `<h2 class="category-title workspace-title">${escapeHTML(label)}</h2>`,
              `<p class="category-subtitle workspace-subtitle">Local, deterministic processing in your browser.</p>`,
            ],
          }),
        ],
      }),
      showSelect
        ? createElement("div", {
            attrs: { class: "category-controls" },
            children: [selectMarkup],
          })
        : "",
      renderCategoryInputs(category),
      createElement("div", {
        attrs: { class: "category-actions workspace-actions" },
        children: [
          buildButton({
            label: "Run",
            dataRole: ROLES.CATEGORY_ACTION,
            classes: "pure-button pure-button-primary wt-primary",
          }),
        ],
      }),
      createElement("div", {
        attrs: {
          class: "category-result workspace-result result",
          "data-role": ROLES.CATEGORY_RESULT,
          "data-state": "idle",
        },
        children: ["Ready — run the operation to see results."],
      }),
    ],
  });
}

