/ui/dom.ts:
export interface HTMLAttrs {
  [key: string]: string;
}

const VOID_TAGS = new Set([
  "area", "base", "br", "col", "embed", "hr", "img",
  "input", "link", "meta", "source", "track", "wbr",
]);

const ATTR_KEY_MAP: Record<string, string> = {
  for: "for",
  className: "class",
};

export function escapeHTML(value: unknown): string {
  const s = String(value ?? "");
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export interface CreateElementOptions {
  attrs?: HTMLAttrs;
  children?: readonly string[];
}

/**
 * Build a minimal HTML element string without touching any browser API.
 * Attribute names are mapped (e.g. className -> class), values are escaped.
 */
export function createElement(
  tag: string,
  options: CreateElementOptions = {},
): string {
  const { attrs = {}, children = [] } = options;

  const attrParts: string[] = [];
  for (const [key, rawValue] of Object.entries(attrs)) {
    const name = ATTR_KEY_MAP[key] ?? key;
    if (rawValue === "" || rawValue == null) {
      attrParts.push(` ${name}`);
    } else {
      attrParts.push(` ${name}="${escapeHTML(rawValue)}"`);
    }
  }
  const attrStr = attrParts.join("");

  if (VOID_TAGS.has(tag.toLowerCase())) {
    return `<${tag}${attrStr} />`;
  }

  const body = children.join("");
  return `<${tag}${attrStr}>${body}</${tag}>`;
}

export interface ButtonOptions {
  label: string;
  dataRole: string;
  type?: "button" | "submit" | "reset";
  classes?: string;
  ariaLabel?: string;
  icon?: string;
  attrs?: HTMLAttrs;
}

/**
 * Build an accessible, type-safe button element string.
 * Icon-only buttons (ariaLabel only, no visible label) are supported.
 */
export function buildButton(options: ButtonOptions): string {
  const {
    label,
    dataRole,
    type = "button",
    classes = "",
    ariaLabel,
    icon,
    attrs = {},
  } = options;

  const finalAttrs: HTMLAttrs = {
    type,
    "data-role": dataRole,
    ...attrs,
  };
  if (classes) {
    finalAttrs.class = classes;
  }
  if (ariaLabel) {
    finalAttrs["aria-label"] = ariaLabel;
  }

  const iconMarkup = icon
    ? `<span class="wt-btn-icon" aria-hidden="true">${escapeHTML(icon)}</span>`
    : "";
  const labelMarkup = label
    ? `<span class="wt-btn-label">${escapeHTML(label)}</span>`
    : "";
  const visibleLabel = ariaLabel && !label ? "" : label;

  return createElement("button", {
    attrs: finalAttrs,
    children: [iconMarkup, labelMarkup].filter(Boolean),
  });
}

export interface TileOptions {
  name: string;
  hint: string;
  dataRole: string;
  icon: string;
  variant: string;
  ariaLabel?: string;
}

/**
 * Build a folder-like category tile (a button element) with icon, name, and hint.
 */
export function buildTile(options: TileOptions): string {
  const { name, hint, dataRole, icon, variant, ariaLabel } = options;

  const finalAttrs: HTMLAttrs = {
    type: "button",
    "data-role": dataRole,
    class: `card card-${variant}`,
  };
  if (ariaLabel) {
    finalAttrs["aria-label"] = ariaLabel;
  }

  const iconEl = createElement("span", {
    attrs: { class: "card-icon", "aria-hidden": "true" },
    children: [escapeHTML(icon)],
  });
  const nameEl = createElement("span", {
    attrs: { class: "card-name" },
    children: [escapeHTML(name)],
  });
  const hintEl = createElement("span", {
    attrs: { class: "card-hint" },
    children: [escapeHTML(hint)],
  });

  return createElement("button", { attrs: finalAttrs, children: [iconEl, nameEl, hintEl] });
}

export interface RowOptions {
  name: string;
  hint?: string;
  dataRole?: string;
  icon?: string;
  selected?: boolean;
  ariaLabel?: string;
}

/**
 * Build a horizontal list row (a button element) for library quick-access or space rows.
 */
export function buildRow(options: RowOptions): string {
  const { name, hint, dataRole, icon, selected, ariaLabel } = options;

  const finalAttrs: HTMLAttrs = { type: "button" };
  if (dataRole) {
    finalAttrs["data-role"] = dataRole;
  }
  finalAttrs.class = selected ? "library-row library-chip-active" : "library-row";
  if (ariaLabel) {
    finalAttrs["aria-label"] = ariaLabel;
  }

  const children: string[] = [];
  if (icon) {
    children.push(
      createElement("span", {
        attrs: { class: "card-icon", "aria-hidden": "true" },
        children: [escapeHTML(icon)],
      }),
    );
  }
  children.push(
    createElement("span", {
      attrs: { class: "library-row-name" },
      children: [escapeHTML(name)],
    }),
  );
  if (hint) {
    children.push(
      createElement("span", {
        attrs: { class: "library-row-hint" },
        children: [escapeHTML(hint)],
      }),
    );
  }

  return createElement("button", { attrs: finalAttrs, children });
}

export interface LabelledFieldOptions {
  id: string;
  label: string;
  type?: string;
  name?: string;
  value?: string;
  placeholder?: string;
  rows?: number;
  required?: boolean;
}

/**
 * Build a labelled native text input or textarea wrapped in a field container.
 */
export function buildLabelledField(options: LabelledFieldOptions): string {
  const { id, label, type = "text", name, value, placeholder, rows, required } = options;

  const labelEl = createElement("label", {
    attrs: { class: "workspace-field-label", for: id },
    children: [escapeHTML(label)],
  });

  const isTextarea = type === "textarea";
  const inputAttrs: HTMLAttrs = {
    id,
    type: isTextarea ? undefined as unknown as string : type,
    name: name ?? "",
    value: value ?? "",
    placeholder: placeholder ?? "",
  };
  if (isTextarea) {
    delete inputAttrs.type;
    inputAttrs.rows = String(rows ?? 6);
  }
  if (required) {
    inputAttrs.required = "";
  }

  const tag = isTextarea ? "textarea" : "input";
  const inputEl = createElement(tag, { attrs: inputAttrs });

  return createElement("div", {
    attrs: { class: "workspace-field" },
    children: [labelEl, inputEl],
  });
}

export interface SelectOption {
  value: string;
  label: string;
}

export interface SelectFieldOptions {
  id: string;
  label: string;
  name: string;
  options: readonly SelectOption[];
  defaultValue?: string;
}

/**
 * Build a labelled native select element with one or more options.
 */
export function buildSelectField(options: SelectFieldOptions): string {
  const { id, label, name, options: opts, defaultValue } = options;

  const labelEl = createElement("label", {
    attrs: { class: "workspace-field-label", for: id },
    children: [escapeHTML(label)],
  });

  const optionEls = opts.map((opt) =>
    createElement("option", {
      attrs: {
        value: opt.value,
        selected: opt.value === defaultValue ? "selected" : undefined as unknown as string,
      },
      children: [escapeHTML(opt.label)],
    }),
  );

  const selectEl = createElement("select", {
    attrs: { id, name, class: "category-select" },
    children: optionEls,
  });

  return createElement("div", {
    attrs: { class: "workspace-field" },
    children: [labelEl, selectEl],
  });
}
